$:node <<'NODE'
"use strict";
const fs=require("node:fs"),assert=require("node:assert/strict"),cp=require("node:child_process");
const file="workspaces/extractor-srs-design/VERIFICATION-PLAN.md";
const evidence="acceptance/results/E2E-008-distinct-41654917999-41654917547.json";
let s=fs.readFileSync(file,"utf8");
const substitutions=[
[
"**Execution status:** **NOT RUN** for every proposed new Terminals test. Source-system historical runs described in Issue #4 are **not** recorded as results for these tests.",
"**Execution status (updated 2026-11-03):** **E2E-008 / EXT-AT-070 PASS**, independently audited and recorded in ["+evidence+"]("+evidence+"). Other case statuses remain as shown in their respective rows. Historical source-system runs are not substitutes for Terminals acceptance evidence."
],
[
"| EXT-AT-070 | EXT-FR-070 | Launch two concurrent exports to same branch | No lost updates; queued/serialized push operations | **NOT RUN** |",
"| EXT-AT-070 | EXT-FR-070 | Launch two concurrent exports to same branch | No lost updates; queued/serialized push operations | **PASS** — [16 remote files verified]("+evidence+") |"
],
[
"**E2E-008 — concurrency:** Dispatch at least two public shares simultaneously, capture both run IDs, allow serial noncancelled publication, prove no overwritten paths and verify all required files for both outputs. **Status: NOT RUN**.",
"**E2E-008 — concurrency:** Dispatch at least two public shares simultaneously, capture both run IDs, allow serial noncancelled publication, prove no overwritten paths and verify all required files for both outputs. **Status: PASS** — distinct-share runs 41654917999 and 41654917547, 16/16 independently verified Git files, two preserved publication commits, zero overwritten paths. [Machine-readable acceptance record]("+evidence+")."
]
];
for(const [before,after] of substitutions){
 assert.equal(s.split(before).length,2,"expected unique pre-update contract not found");
 s=s.replace(before,after);
}
fs.writeFileSync(file,s);
function gh(args){const r=cp.spawnSync("gh",["api",...args],{encoding:"utf8",maxBuffer:2*1024*1024});if(r.status!==0)throw Error((r.stderr||"").slice(0,1000));return JSON.parse(r.stdout);}
const remote=gh(["repos/BestNameYet/Terminals/contents/"+file]);
assert.equal(remote.sha,"29ea90105bba0efd6e61a64ce64e7801f93dbf8a","concurrent change detected");
const write=gh(["-X","PUT","repos/BestNameYet/Terminals/contents/"+file,
 "-f","message=Record verified E2E-008 concurrency acceptance in verification plan",
 "-f","content="+Buffer.from(s).toString("base64"),"-f","sha="+remote.sha]);
const check=gh(["repos/BestNameYet/Terminals/contents/"+file]);
assert.equal(Buffer.from(check.content.replace(/\s/g,""),"base64").toString("utf8"),s);
console.log(JSON.stringify({status:"PASS",updated:file,commit:write.commit.sha,sha:check.sha,evidence,readback_verified:true,statuses:["E2E-008 PASS","EXT-AT-070 PASS"]}));
NODE
